package cli

import (
	"encoding/json"
	"fmt"
	"net/url"
	"os"
	"path/filepath"

	"github.com/spf13/cobra"
)

func newReportCmd(flags *rootFlags) *cobra.Command {
	var (
		toDir     string
		neighbors bool
		radius    float64
	)
	cmd := &cobra.Command{
		Use:   "report <RC>",
		Short: "Bundle expediente: DNPRC + vecinas + mapa WMS en un directorio listo para anexar a informe",
		Long: "Compone Consulta_DNPRC + Consulta_RCCOOR_Distancia + WMS GetMap en un directorio con:\n" +
			"  - data.json       (datos DNPRC completos de la finca)\n" +
			"  - neighbors.json  (RCs vecinas si --neighbors)\n" +
			"  - parts.csv       (sub-partes urbanas de la finca)\n" +
			"  - map.png         (PNG del visor WMS centrado en la finca)\n" +
			"  - map-url.txt     (URL directa al WMS por si --map-png falla)\n\n" +
			"Reemplaza la fontanería de 4 herramientas (pycatastro + R CatastRo + QGIS + screenshot)\n" +
			"que un técnico de expediente hace hoy.",
		Example: "  catastro-pp-cli report 0545206VK4704F0001RE --neighbors --to ./expediente-A12/",
		Annotations: map[string]string{
			"mcp:read-only": "true",
		},
		RunE: func(cmd *cobra.Command, args []string) error {
			if len(args) == 0 {
				return cmd.Help()
			}
			rc := args[0]
			if toDir == "" {
				toDir = "./report-" + rc
			}
			if dryRunOK(flags) {
				fmt.Fprintf(cmd.OutOrStdout(),
					`{"would_compose":["DNPRC","RCCOOR_Distancia","WMS"],"rc":%q,"out_dir":%q}`+"\n",
					rc, toDir)
				return nil
			}
			if err := os.MkdirAll(toDir, 0755); err != nil {
				return fmt.Errorf("mkdir %s: %w", toDir, err)
			}

			c, err := flags.newClient()
			if err != nil {
				return err
			}

			// Track only files actually written and surface partial-failure
			// reasons in a "warnings" field so callers can detect drift
			// between the manifest and disk.
			var written []string
			var warnings []string

			// 1. DNPRC for full property data
			data, err := c.Get("/COVCCallejero.svc/json/Consulta_DNPRC", map[string]string{"RefCat": rc})
			if err != nil {
				return fmt.Errorf("DNPRC: %w", err)
			}
			if err := writeFile(filepath.Join(toDir, "data.json"), data); err != nil {
				return err
			}
			written = append(written, "data.json")

			// 2. Parts CSV (best-effort, from DNPRC sub-parts)
			parts := extractParts(data)
			partsCSV := "subparcela,uso,superficie,coef_propiedad\n"
			for _, p := range parts {
				partsCSV += fmt.Sprintf("%v,%v,%v,%v\n", p["subparcela"], p["uso"], p["superficie"], p["coef"])
			}
			if err := os.WriteFile(filepath.Join(toDir, "parts.csv"), []byte(partsCSV), 0644); err != nil {
				return err
			}
			written = append(written, "parts.csv")

			// 3. Coordenadas + Neighbors
			coordsData, coordsErr := coordenadasGET(flags.timeout, "Consulta_CPMRC", map[string]string{
				"SRS": "EPSG:4326", "RC": rc,
			})
			lon, lat := "", ""
			if coordsErr == nil {
				if werr := writeFile(filepath.Join(toDir, "coords.json"), coordsData); werr == nil {
					written = append(written, "coords.json")
				} else {
					warnings = append(warnings, fmt.Sprintf("coords.json: %v", werr))
				}
				var c struct {
					Coordinates []struct {
						Lon, Lat string
					} `json:"coordinates"`
				}
				if json.Unmarshal(coordsData, &c) == nil && len(c.Coordinates) > 0 {
					lon, lat = c.Coordinates[0].Lon, c.Coordinates[0].Lat
				}
			} else {
				warnings = append(warnings, fmt.Sprintf("Consulta_CPMRC: %v", coordsErr))
			}

			gotNeighbors := false
			if neighbors {
				if lon == "" || lat == "" {
					warnings = append(warnings, "neighbors skipped: coordinates unavailable")
				} else {
					nbData, nbErr := coordenadasGET(flags.timeout, "Consulta_RCCOOR_Distancia", map[string]string{
						"SRS": "EPSG:4326", "Coordenada_X": lon, "Coordenada_Y": lat,
					})
					if nbErr == nil {
						if werr := writeFile(filepath.Join(toDir, "neighbors.json"), nbData); werr == nil {
							written = append(written, "neighbors.json")
							gotNeighbors = true
						} else {
							warnings = append(warnings, fmt.Sprintf("neighbors.json: %v", werr))
						}
					} else {
						warnings = append(warnings, fmt.Sprintf("Consulta_RCCOOR_Distancia: %v", nbErr))
					}
				}
			}

			// 4. WMS GetMap URL + PNG download (each tracked separately).
			if lon != "" && lat != "" {
				wmsURL := buildWMSGetMap(lon, lat, 0.001)
				if werr := os.WriteFile(filepath.Join(toDir, "map-url.txt"), []byte(wmsURL+"\n"), 0644); werr == nil {
					written = append(written, "map-url.txt")
				} else {
					warnings = append(warnings, fmt.Sprintf("map-url.txt: %v", werr))
				}
				if derr := downloadFile(wmsURL, filepath.Join(toDir, "map.png")); derr == nil {
					written = append(written, "map.png")
				} else {
					warnings = append(warnings, fmt.Sprintf("map.png: %v", derr))
				}
			} else {
				warnings = append(warnings, "WMS map skipped: coordinates unavailable")
			}

			summary := map[string]any{
				"rc":            rc,
				"out_dir":       toDir,
				"files":         written,
				"parts_count":   len(parts),
				"radius_m":      radius,
				"has_neighbors": gotNeighbors,
			}
			if len(warnings) > 0 {
				summary["warnings"] = warnings
			}
			b, _ := json.MarshalIndent(summary, "", "  ")
			fmt.Fprintln(cmd.OutOrStdout(), string(b))
			return nil
		},
	}
	cmd.Flags().StringVar(&toDir, "to", "", "Directorio destino (default: ./report-<RC>)")
	cmd.Flags().BoolVar(&neighbors, "neighbors", false, "Incluir vecinas (llama a RCCOOR_Distancia)")
	cmd.Flags().Float64Var(&radius, "radius", 50.0, "Radio para vecinas en metros")
	return cmd
}

func writeFile(path string, data []byte) error {
	return os.WriteFile(path, data, 0644)
}

func extractParts(data json.RawMessage) []map[string]any {
	out := []map[string]any{}
	// Catastro nests sub-parts under bico.lcons.cons[*] or bico.parts[*]; walk the tree.
	var v any
	if json.Unmarshal(data, &v) != nil {
		return out
	}
	walkForArrays(v, "cons", &out)
	walkForArrays(v, "lous", &out)
	// Map keys to readable names (best-effort)
	mapped := make([]map[string]any, 0, len(out))
	for _, item := range out {
		row := map[string]any{}
		for k, v := range item {
			lk := k
			if k == "stl" || k == "sup" {
				lk = "superficie"
			}
			if k == "luso" || k == "uso" {
				lk = "uso"
			}
			if k == "cn" {
				lk = "subparcela"
			}
			row[lk] = v
		}
		mapped = append(mapped, row)
	}
	return mapped
}

func walkForArrays(v any, key string, out *[]map[string]any) {
	switch t := v.(type) {
	case map[string]any:
		if arr, ok := t[key].([]any); ok {
			for _, item := range arr {
				if m, ok := item.(map[string]any); ok {
					*out = append(*out, m)
				}
			}
		}
		for _, sub := range t {
			walkForArrays(sub, key, out)
		}
	case []any:
		for _, sub := range t {
			walkForArrays(sub, key, out)
		}
	}
}

func buildWMSGetMap(lon, lat string, halfDegrees float64) string {
	// Build a small bbox around the centroid; 0.001 deg ~ 100 m
	var x, y float64
	fmt.Sscanf(lon, "%f", &x)
	fmt.Sscanf(lat, "%f", &y)
	minX, minY := x-halfDegrees, y-halfDegrees
	maxX, maxY := x+halfDegrees, y+halfDegrees
	q := url.Values{}
	q.Set("REQUEST", "GetMap")
	q.Set("SERVICE", "WMS")
	q.Set("VERSION", "1.3.0")
	q.Set("LAYERS", "CP.CadastralParcel")
	q.Set("FORMAT", "image/png")
	q.Set("BBOX", fmt.Sprintf("%f,%f,%f,%f", minY, minX, maxY, maxX))
	q.Set("CRS", "EPSG:4326")
	q.Set("WIDTH", "800")
	q.Set("HEIGHT", "600")
	q.Set("TRANSPARENT", "false")
	return "https://ovc.catastro.meh.es/cartografia/INSPIRE/spadgcwms.aspx?" + q.Encode()
}

func downloadFile(u, path string) error {
	resp, err := httpGetSimple(u)
	if err != nil {
		return err
	}
	return os.WriteFile(path, resp, 0644)
}
